// 32 bit Murmur3 hash
__device__ uint32_t hash(uint32_t k)
{
	k ^= k >> 16;
	k *= 0x85ebca6b;
	k ^= k >> 13;
	k *= 0xc2b2ae35;
	k ^= k >> 16;
	return k & (kHashTableCapacity-1);}

